import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.Cz0TtJv6.js";const k=JSON.parse('{"title":"API keys","description":"Helius RPC, Jupiter, and GMGN — where to sign up, how to copy keys into the dashboard wizard or Settings.","frontmatter":{"title":"API keys","description":"Helius RPC, Jupiter, and GMGN — where to sign up, how to copy keys into the dashboard wizard or Settings."},"headers":[],"relativePath":"api-keys.md","filePath":"api-keys.md","lastUpdated":1786716878000}'),r={name:"api-keys.md"};function n(o,e,l,p,d,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="api-keys" tabindex="-1">API keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API keys&quot;">​</a></h1><p>One checklist for every external key the bot uses. Paste them in the first-run <strong>setup wizard</strong> or <strong>Settings → Wallet &amp; secrets</strong> (writes to <code>data/.env</code> on your volume).</p><table tabindex="0"><thead><tr><th>Key</th><th>Required?</th><th>Free tier?</th><th>What it powers</th></tr></thead><tbody><tr><td><strong><code>RPC_URL</code></strong> (Helius)</td><td><strong>Yes</strong></td><td>Yes (signup)</td><td>On-chain reads, vetting, tx simulation</td></tr><tr><td><strong><code>JUPITER_API_KEY</code></strong></td><td><strong>Yes</strong> before live</td><td>Yes</td><td>Exit swaps (token → SOL), profit-burn, <code>simulate-zap</code></td></tr><tr><td><strong><code>GMGN_API_KEY</code></strong></td><td>Optional (recommended)</td><td>Yes</td><td>Trending discovery, smart-money feeds, honeypot/sell-tax vetting</td></tr></tbody></table><p>Without GMGN the bot still runs on Meteora datapi + RPC + RugCheck — GMGN adds score bonuses (capped at +10) and extra security flags.</p><hr><h2 id="helius-rpc-rpc-url" tabindex="-1">Helius RPC (<code>RPC_URL</code>) <a class="header-anchor" href="#helius-rpc-rpc-url" aria-label="Permalink to &quot;Helius RPC (`RPC_URL`)&quot;">​</a></h2><p>We suggest <a href="https://www.helius.dev/" target="_blank" rel="noreferrer">Helius</a> for Solana mainnet. Public RPC endpoints work for a smoke test but rate-limit during live trading.</p><ol><li>Sign up at <a href="https://dashboard.helius.dev/signup" target="_blank" rel="noreferrer">dashboard.helius.dev/signup</a></li><li>Create a project → open <strong>RPC</strong> → copy the <strong>Mainnet</strong> HTTPS URL</li><li>Paste into the wizard or <code>RPC_URL</code> in Settings / <code>.env</code></li></ol><p>Example: <code>https://mainnet.helius-rpc.com/?api-key=YOUR_KEY</code></p><p><a href="https://www.helius.dev/docs/api-reference/endpoints" target="_blank" rel="noreferrer">Helius RPC endpoint docs</a></p><hr><h2 id="jupiter-api-key-jupiter-api-key" tabindex="-1">Jupiter API key (<code>JUPITER_API_KEY</code>) <a class="header-anchor" href="#jupiter-api-key-jupiter-api-key" aria-label="Permalink to &quot;Jupiter API key (`JUPITER_API_KEY`)&quot;">​</a></h2><p>Live exits route through Jupiter. Paper simulates fills but you still want a key for <code>npm run simulate-zap</code> before going live.</p><ol><li>Open <a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">developers.jup.ag/portal</a> and sign in (Google, GitHub, or email)</li><li>Create or join a <strong>team</strong> in your organization</li><li><strong>API Keys</strong> → <strong>Create</strong> → name it (e.g. <code>dlmmbot-prod</code>)</li><li>Copy the key <strong>immediately</strong> — Jupiter shows the full value <strong>once</strong></li><li>Paste into the wizard or <code>JUPITER_API_KEY</code> in Settings / <code>.env</code></li></ol><p>Free tier (1 req/s) is enough to start.</p><ul><li><a href="https://developers.jup.ag/docs/portal/setup" target="_blank" rel="noreferrer">Jupiter setup guide</a></li><li><a href="https://developers.jup.ag/docs/portal/api-keys" target="_blank" rel="noreferrer">API keys docs</a></li></ul><hr><h2 id="gmgn-api-key-gmgn-api-key-—-optional" tabindex="-1">GMGN API key (<code>GMGN_API_KEY</code>) — optional <a class="header-anchor" href="#gmgn-api-key-gmgn-api-key-—-optional" aria-label="Permalink to &quot;GMGN API key (`GMGN_API_KEY`) — optional&quot;">​</a></h2><p><a href="https://gmgn.ai/" target="_blank" rel="noreferrer">GMGN</a> feeds trending tokens and smart-money flow into the scanner, and adds honeypot / sell-tax checks at vet time. <strong>Query-only</strong> — the bot never uses GMGN to trade, so you do <strong>not</strong> need <code>GMGN_PRIVATE_KEY</code>.</p><h3 id="_1-generate-a-key-pair-ed25519" tabindex="-1">1. Generate a key pair (Ed25519) <a class="header-anchor" href="#_1-generate-a-key-pair-ed25519" aria-label="Permalink to &quot;1. Generate a key pair (Ed25519)&quot;">​</a></h3><p>Pick one method:</p><p><strong>Terminal (Linux / macOS / WSL / VPS):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genpkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_private.pem</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_private.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pubout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_public.pem</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_public.pem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # copy this whole block for step 2</span></span></code></pre></div><p>Store <code>gmgn_private.pem</code> somewhere safe if you ever use GMGN trading tools yourself — <strong>do not</strong> paste the private key into DLMM Bot.</p><p><strong>GUI:</strong> follow <a href="https://docs.gmgn.ai/index/generate-public-key" target="_blank" rel="noreferrer">GMGN → Generate Public Key</a> and download their key-generator app → <strong>Generate 1 Key Pair</strong> → copy the <strong>public</strong> key.</p><div class="warning custom-block"><p class="custom-block-title">Public key format</p><p>Paste the <strong>entire</strong> public key including the <code>-----BEGIN PUBLIC KEY-----</code> and <code>-----END PUBLIC KEY-----</code> lines into GMGN&#39;s form.</p></div><h3 id="_2-create-the-api-key-on-gmgn" tabindex="-1">2. Create the API key on GMGN <a class="header-anchor" href="#_2-create-the-api-key-on-gmgn" aria-label="Permalink to &quot;2. Create the API key on GMGN&quot;">​</a></h3><ol><li>Sign up at <a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">gmgn.ai/ai</a> (email, wallet, or Telegram)</li><li>Open the <strong>API key</strong> panel</li><li>Paste your <strong>public key</strong> → submit → copy the <strong>API Key</strong> GMGN shows you</li><li>Paste that value into the wizard or <code>GMGN_API_KEY</code> in Settings / <code>.env</code></li></ol><p>That&#39;s it — only <code>GMGN_API_KEY</code> goes in the bot env. Rate limit is ~1 req/s; the farmer paces calls and degrades gracefully if GMGN is missing or rate-limited.</p><ul><li><a href="https://docs.gmgn.ai/index/gmgn-agent-api" target="_blank" rel="noreferrer">GMGN Agent API overview</a></li><li><a href="https://docs.gmgn.ai/index/generate-public-key" target="_blank" rel="noreferrer">Generate public key (full guide)</a></li></ul><hr><h2 id="quick-copy-checklist" tabindex="-1">Quick copy checklist <a class="header-anchor" href="#quick-copy-checklist" aria-label="Permalink to &quot;Quick copy checklist&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># data/.env (or wizard / Settings)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RPC_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://mainnet.helius-rpc.com/?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api-key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_HELIUS_KEY</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JUPITER_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_jupiter_key</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GMGN_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_gmgn_key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # optional</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./easy">Easy setup</a> · <a href="./advanced">Advanced setup</a></li><li><a href="./configuration">Configuration</a> — <code>[gmgn]</code> toggles and vetting gates</li><li><a href="./faq#do-i-need-the-gmgn-api-key">FAQ → GMGN</a></li></ul>',35)])])}const c=t(r,[["render",n]]);export{k as __pageData,c as default};
